                        + " amount=" + added.amount() + " date=" + added.date());
                if (added.lateEntry()) {
                    audit.record("LATE_ENTRY sheet=" + id + " by=" + by + " person=" + name
                            + " amount=" + added.amount() + " date=" + added.date());
